    #[cfg(feature = "aura-containers")]
    c_aura_container_util::register(state)?;
    #[cfg(any(feature = "aura-containers", feature = "retail-12-0-0"))]
    c_secrets::register(state)?;
    register_specialization_and_model_tables(state)?;
    register_glue_and_display_tables(state)?;
    #[cfg(feature = "retail-12-0-0")]
    patch_retired_members::mark_retired_members(state)?;
    register_auxiliary_utility_tables(state)
}

fn register_specialization_and_model_tables(state: &mut LuaState) -> LuaResult<()> {
    c_spec::register_c_specialization_info(state)?;
    permanent_shims::c_model_info::register_c_model_info(state)?;
    Ok(())
}

fn register_glue_and_display_tables(state: &mut LuaState) -> LuaResult<()> {
    c_glue::register_c_glue(state)?;
    c_login::register_c_login(state)?;
    permanent_shims::c_ui::register_c_ui(state)
}

fn register_auxiliary_utility_tables(state: &mut LuaState) -> LuaResult<()> {
    register_token_texture_xml_tables(state)
}

fn register_token_texture_xml_tables(state: &mut LuaState) -> LuaResult<()> {
    c_string_util::register_c_string_util(state)?;
    c_string_util_decimal::register_escape_decimal_non_printables(state)?;
    c_pvp::register_c_pvp_surface(state)?;
    c_ping_secure::register_c_ping_secure_surface(state)?;
    #[cfg(feature = "retail-12-0-0")]
    c_ping_cooldown::register(state)?;
    #[cfg(feature = "retail-12-0-0")]
    c_ping_texture_kits::register(state)?;
    c_wowtoken_secure::register_c_wowtoken_secure(state)?;
    c_wow_token_public::register_c_wow_token_public(state)?;
    c_texture::register_c_texture(state)?;
    c_ui_file_asset::register_c_ui_file_asset(state)?;
    c_xml_util::register_c_xml_util(state)
}

//! Dependency-closure loading without panel, startup, or process fixtures.

use std::path::{Path, PathBuf};

use wow_ui_sim::loader::{
    BlizzardAddonOverride, discover_blizzard_addon_closure_for_screen_with_overrides, load_addon,
};
use wow_ui_sim::lua_api::WowLuaEnv;
use wow_ui_sim::screen::ScreenKind;

pub fn blizzard_ui_dir() -> PathBuf {
    wow_ui_sim::paths::default_blizzard_ui_addons_path()
        .expect("Blizzard UI cache should be available")
}

pub fn load_blizzard_addon_closure_into_env(
    env: &WowLuaEnv,
    ui_dir: &Path,
    roots: &[&str],
    overrides: &[BlizzardAddonOverride<'_>],
) -> Vec<String> {
    load_blizzard_addon_closure_for_screen_into_env(env, ui_dir, ScreenKind::Game, roots, overrides)
}

pub fn load_blizzard_addon_closure_for_screen_into_env(
    env: &WowLuaEnv,
    ui_dir: &Path,
    screen: ScreenKind,
    roots: &[&str],
    overrides: &[BlizzardAddonOverride<'_>],
) -> Vec<String> {
    let addons =
        discover_blizzard_addon_closure_for_screen_with_overrides(ui_dir, screen, roots, overrides);
    load_discovered_blizzard_addons_into_env(env, addons)
}

pub fn load_discovered_blizzard_addons_into_env(
    env: &WowLuaEnv,
    addons: Vec<(String, PathBuf)>,
) -> Vec<String> {
    let mut loaded = Vec::new();
    for (name, toc_path) in addons {
        if !is_addon_loaded(env, &name) {
            if let Err(error) = load_addon(&env.loader_env(), &toc_path) {
                panic!("{name} should load in the Blizzard addon closure harness: {error}");
            }
        }
        loaded.push(name);
    }
    loaded
}

fn is_addon_loaded(env: &WowLuaEnv, name: &str) -> bool {
    env.state()
        .borrow()
        .addons
        .iter()
        .any(|addon| addon.folder_name == name && addon.loaded)
}

pub fn build_blizzard_addon_closure_env(
    ui_dir: &Path,
    roots: &[&str],
    overrides: &[BlizzardAddonOverride<'_>],
) -> (WowLuaEnv, Vec<String>) {
    let env = new_blizzard_addon_env(ui_dir);
    let loaded = load_blizzard_addon_closure_into_env(&env, ui_dir, roots, overrides);
    (env, loaded)
}

pub fn new_blizzard_addon_env(ui_dir: &Path) -> WowLuaEnv {
    new_blizzard_addon_env_for_screen(ui_dir, ScreenKind::Game)
}

pub(super) fn new_blizzard_addon_env_for_screen(ui_dir: &Path, screen: ScreenKind) -> WowLuaEnv {
    let env = WowLuaEnv::new().expect("failed to create Lua environment");
    env.set_screen_size(1024.0, 768.0);
    env.set_screen_mode(screen);

    let ui = ui_dir.to_path_buf();
    {
        let mut state = env.state().borrow_mut();
        state.addon_base_paths = vec![ui];
    }

    env
}

